-- | The RE2 Unicode tables cel-python's regexes depend on.
--
-- RE2 (Unicode 15.1.0) decides regex classes and case folding; the tables
-- are generated by @gen/gen-unicode-tables.py@ and decoded once, on first
-- use. CPython 3.14's own predicates (Unicode 16.0.0: printability,
-- whitespace, decimal digits) are petrus-json's "Petrus.Json.PythonText".
module Petrus.Cel.Unicode
  ( -- * Range sets
    RangeSet
  , rangeSet
  , rangeSetRanges
  , member
    -- * RE2 tables
  , re2Category
  , re2Script
  , re2Orbit
  , re2Orbits
  ) where

import Data.Array.Unboxed (UArray, bounds, listArray, (!))
import Data.Char (isHexDigit)
import Data.IntMap.Strict qualified as IntMap
import Data.List (sortOn)
import Data.Map.Strict qualified as Map
import Numeric (readHex)

import Petrus.Cel.Unicode.Tables qualified as Tables

-- | A set of code points as sorted, disjoint, non-adjacent inclusive ranges.
data RangeSet = RangeSet [(Int, Int)] (UArray Int Int) (UArray Int Int)

-- | Normalise arbitrary inclusive ranges into a 'RangeSet'.
rangeSet :: [(Int, Int)] -> RangeSet
rangeSet input =
  let merged = merge (sortOn fst [r | r@(lo, hi) <- input, lo <= hi])
      n = length merged
   in RangeSet merged (listArray (0, n - 1) (map fst merged)) (listArray (0, n - 1) (map snd merged))
  where
    merge ((a, b) : (c, d) : rest)
      | c <= b + 1 = merge ((a, max b d) : rest)
      | otherwise = (a, b) : merge ((c, d) : rest)
    merge rest = rest

-- | The normalised ranges of a set.
rangeSetRanges :: RangeSet -> [(Int, Int)]
rangeSetRanges (RangeSet rs _ _) = rs

-- | Binary-search membership.
member :: Int -> RangeSet -> Bool
member c (RangeSet _ los his) = go lo0 hi0
  where
    (lo0, hi0) = bounds los
    go lo hi
      | lo > hi = False
      | otherwise =
          let mid = (lo + hi) `div` 2
           in if c < los ! mid
                then go lo (mid - 1)
                else c <= his ! mid || go (mid + 1) hi

-- | Decode @"lo-hi lo hi-..."@ hexadecimal runs.
decodeRanges :: String -> [(Int, Int)]
decodeRanges = map one . words
  where
    one w = case break (== '-') w of
      (a, '-' : b) -> (hex a, hex b)
      (a, _) -> (hex a, hex a)

hex :: String -> Int
hex s = case readHex (filter isHexDigit s) of
  [(v, "")] -> v
  _ -> error ("Petrus.Cel.Unicode: bad table entry " <> show s)

splitOn :: Char -> String -> [String]
splitOn sep s = case break (== sep) s of
  (a, _ : rest) -> a : splitOn sep rest
  (a, []) -> [a]

namedSets :: String -> Map.Map String RangeSet
namedSets table =
  Map.fromList
    [ (name, rangeSet (decodeRanges body))
    | entry <- splitOn ';' table
    , (name, '=' : body) <- [break (== '=') entry]
    ]

categorySets :: Map.Map String RangeSet
categorySets =
  let two = namedSets Tables.re2Categories
      one =
        Map.fromListWith
          (\a b -> rangeSet (rangeSetRanges a <> rangeSetRanges b))
          [(take 1 name, set) | (name, set) <- Map.toList two]
   in Map.union two one
{-# NOINLINE categorySets #-}

scriptSets :: Map.Map String RangeSet
scriptSets = namedSets Tables.re2Scripts
{-# NOINLINE scriptSets #-}

-- | An RE2 general category (one or two letters, e.g. @L@ or @Lu@).
re2Category :: String -> Maybe RangeSet
re2Category name = Map.lookup name categorySets

-- | An RE2 script (e.g. @Greek@).
re2Script :: String -> Maybe RangeSet
re2Script name = Map.lookup name scriptSets

orbitMap :: IntMap.IntMap [Int]
orbitMap =
  foldl'
    (\m orbit -> foldl' (\acc c -> IntMap.insert c orbit acc) m orbit)
    IntMap.empty
    re2Orbits
{-# NOINLINE orbitMap #-}

-- | The RE2 case-folding orbit of a character (itself when it has none).
re2Orbit :: Int -> [Int]
re2Orbit c = IntMap.findWithDefault [c] c orbitMap

-- | Every RE2 case-folding orbit with more than one member.
re2Orbits :: [[Int]]
re2Orbits = [map hex (words entry) | entry <- splitOn ';' Tables.re2CaseOrbits]
{-# NOINLINE re2Orbits #-}
